/*
  Placeholder Chart.js shim
  - This is NOT the real Chart.js library.
  - It prevents "Chart is not defined" errors and provides a minimal API so the page doesn't crash.
  - Replace with the official UMD build for full chart rendering:
    https://cdn.jsdelivr.net/npm/chart.js/dist/chart.umd.min.js
*/
(function(window){
    if (typeof window.Chart !== 'undefined') return;

    function DummyChart(ctx, config) {
        console.warn('Dummy Chart used: real Chart.js not found. Charts will not render. Replace public/js/chart.min.js with the official Chart.js UMD build.');
        this.ctx = ctx;
        this.config = config || {};
        this.data = (this.config.data) ? JSON.parse(JSON.stringify(this.config.data)) : { labels: [], datasets: [] };
    }

    DummyChart.prototype.update = function(mode){ /* no-op */ };
    DummyChart.prototype.destroy = function(){ /* no-op */ };

    // expose minimal constructor
    window.Chart = DummyChart;
})(window);
